下面用 JS 模拟「N 个 goroutine 各自通过 channel 汇报完成、单一收集者汇总」。输出是什么？

```js
class Chan {
  constructor(cap = 0) { this.cap = cap; this.buf = []; this.putQ = []; this.takeQ = []; }
  put(v) { return new Promise(res => {
    if (this.takeQ.length) { const t = this.takeQ.shift(); t(v); res(); return; }
    if (this.buf.length < this.cap) { this.buf.push(v); res(); return; }
    this.putQ.push({ v, res });
  }); }
  take() { return new Promise(res => {
    if (this.buf.length) { const v = this.buf.shift(); if (this.putQ.length) { const p = this.putQ.shift(); this.buf.push(p.v); p.res(); } res(v); return; }
    if (this.putQ.length) { const p = this.putQ.shift(); res(p.v); p.res(); return; }
    this.takeQ.push(res);
  }); }
}
const ch = new Chan();
let done = 0; const N = 200;
for (let i = 0; i < N; i++) { (async () => { await ch.put(1); })(); }
(async () => { for (let i = 0; i < N; i++) { await ch.take(); done++; } console.log("并发 goroutine 完成数:", done); })();
```

