const ch = new Chan(1000);
let shared = 0;
const collector = (async () => { let sum = 0; for (let i = 0; i < 1000; i++) sum += await ch.take(); return sum; })();
for (let i = 0; i < 1000; i++) { (async () => { shared++; await ch.put(1); })(); }
collector.then(total => console.log("channel 汇总:", total, "shared:", shared));

function runMiddleware(handlers, ctx) {
  let i = 0;
  function next() {
    if (ctx.isAborted()) return;
    if (i >= handlers.length) return;
    const h = handlers[i++]; h(ctx, next);
  }
  next();
}
function makeCtx() {
  const logs = []; let aborted = false;
  return { logs, abort() { aborted = true; }, isAborted() { return aborted; } };
}
const c1 = makeCtx();
runMiddleware([
  (c, n) => { c.logs.push("m1 before"); n(); c.logs.push("m1 after"); },
  (c, n) => { c.logs.push("m2 before"); n(); c.logs.push("m2 after"); },
  (c, n) => { c.logs.push("handler"); n(); },
], c1);
console.log(c1.logs.join(" -> "));
const c2 = makeCtx();
runMiddleware([
  (c, n) => { c.logs.push("auth"); n(); },
  (c, n) => { c.logs.push("ratelimit: 超限，中断"); c.abort(); n(); },
  (c, n) => { c.logs.push("handler(不应执行)"); n(); },
  (c, n) => { c.logs.push("after(不应执行)"); n(); },
], c2);
console.log(c2.logs.join(" -> "));
console.log("aborted =", c2.isAborted());

