```js
function divide(a, b) { if (b === 0) return [null, "division by zero"]; return [a / b, null]; }
function useQuotient(x, y) {
  const [q, err] = divide(x, y);
  if (err !== null) return "错误:" + err;
  return "商=" + q;
}
console.log(useQuotient(10, 2));
console.log(useQuotient(10, 0));
function greetable(obj) {
  if (typeof obj.Greet === "function") return obj.Greet();
  return "不是 Greetable";
}
console.log(greetable({ Greet() { return "Woof"; } }));
console.log(greetable({ }));
